python3 - <<'PYEOF'
p='packs/basics/tasks/baselining/worker.mjs'
s=open(p).read()
old = """import {
  resolveDelivery, pullCreateError, landDelivery,
  pullDisposition, mergeReason, failureSummary, deleteBranch,
} from '../../../../engine/scheduler/land-pr.mjs';"""
new = """import {
  resolveDelivery, pullCreateError, landDelivery,
  pullDisposition, mergeReason, failureSummary, deleteBranch,
} from '../../../../engine/scheduler/land-pr.mjs';
// The skew guard, from the engine so BOTH mechanisms read one definition (#768).
import { servedBy } from '../../../../engine/served-by.mjs';"""
assert s.count(old)==1
s=s.replace(old,new)

old2 = """  const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);"""
new2 = """  // A repo the update flows serve is not this mechanism's to converge (#768's skew
  // risk). Stepping aside is the FIRST thing after reading the declaration and
  // before any clone or write: two mechanisms converging one mount would race on
  // the same files, and the loser's write reads as drift the winner then repairs,
  // nightly, forever. Quiet and agentless — a repo served elsewhere is not an
  // anomaly, so there is nothing here for a human to look at.
  //
  // A member's copy of this worker is only as new as its last converge, so a repo
  // flipped before its mount carries this check keeps baselining for one more
  // cycle. That is the safe direction of that lag: it converges twice by the old
  // mechanism rather than falling between the two.
  const served = servedBy(priorRaw);
  if (served.mechanism !== 'baselining') {
    console.log(`baselining: this repo is served by the ${served.mechanism} flow — standing down`);
    return;
  }
  if (served.invalid !== undefined) {
    console.log(`baselining: maintenance.mechanism "${served.invalid}" is not a mechanism — proceeding as ${served.mechanism}`);
  }

  const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);"""
assert s.count(old2)==1
s=s.replace(old2,new2)
open(p,'w').write(s)
PYEOF
node -e "import('./packs/basics/tasks/baselining/worker.mjs').then(()=>console.log('worker loads'))"

python3 - <<'PYEOF'
p='packs-tests/basics/baselining-worker.test.mjs'
s=open(p).read()
s += """
test('the worker stands down for a repo the update flows serve', async () => {
  // The skew guard at its only load-bearing call site. Driven through the real
  // main() against a real repo directory: the guard must run BEFORE the clone, so a
  // test that stubbed the clone would prove nothing about the ordering that matters.
  const { main } = await import('../../packs/basics/tasks/baselining/worker.mjs');
  const root = mkdtempSync(join(tmpdir(), 'claudinite-skew-'));
  try {
    writeFileSync(join(root, '.claudinite-checks.json'), `${JSON.stringify({
      packs: ['basics'],
      maintenance: { delivery: 'auto-merge', mechanism: 'updates' },
      claudinite: { updated: '2026-08-12T00:00:00Z', ref: 'abc123' },
    }, null, 2)}\\n`);

    const said = [];
    const log = console.log;
    console.log = (...a) => said.push(a.join(' '));
    try {
      await main();
    } finally { console.log = log; }
    assert.match(said.join('\\n'), /served by the updates flow — standing down/);
    // Nothing was cloned, converged or written: the mount is still absent.
    assert.ok(!existsSync(join(root, '.claudinite', 'shared')));
  } finally { rmSync(root, { recursive: true, force: true }); }
});
"""
open(p,'w').write(s)
PYEOF
